public class DebuggerTimeProvider : ComponentProviderAdapter {
	private static readonly AutoConfigState.ClassHandler<DebuggerTimeProvider> CONFIG_STATE_HANDLER =
		AutoConfigState.wireHandler(typeof(DebuggerTimeProvider), MethodHandles.lookup());

	interface GoToTimeAction {
		string NAME = "Go To Time";
		string DESCRIPTION = "Go to a specific time, optionally using emulation";
		string GROUP = GROUP_TRACE;
		Icon ICON = ICON_TIME;
